// Every MAME romset of the boards Demul emulates: its board, whether Demul knows it, MAME's title.
//
// Read from demul-sets.tsv, embedded in this assembly and generated by tools\demul-sets\make-sets.py
// from MAME's -listxml (the board: the BIOS a set's romof leads to) and demul.exe's own strings (known:
// the set's name is in Demul's game table). The import filter (DemulLbImport) sorts a wizard's list with
// it, by the file's name alone - the one thing Demul goes by, "-rom=<romname>".

using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;

namespace LbIntegrations.Demul
{
    internal sealed class DemulSet
    {
        public string Name;
        /// <summary>"Naomi", "Naomi 2", "Atomiswave", "Hikaru", "System SP", "CV1000", "Gaelco" - or "BIOS".</summary>
        public string Board;
        /// <summary>The set's name is in demul.exe. Not a promise that it plays.</summary>
        public bool Known;
        public string Title;
        /// <summary>MAME's parent set (cloneof), or null.</summary>
        public string Parent;
        /// <summary>A Naomi GD-ROM set's disc: the CHD's name without ".chd" (MAME's &lt;disk&gt;), or null - a cartridge.</summary>
        public string GdRom;
    }

    internal static class DemulSets
    {
        public const string Bios = "BIOS";

        private static Dictionary<string, DemulSet> _sets;

        /// <summary>By set name, case-insensitive. Empty, never null, if the resource cannot be read.</summary>
        public static Dictionary<string, DemulSet> All
        {
            get
            {
                if (_sets != null) return _sets;
                var sets = new Dictionary<string, DemulSet>(StringComparer.OrdinalIgnoreCase);
                try
                {
                    using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream("demul-sets.tsv");
                    using var reader = new StreamReader(stream);
                    string line;
                    while ((line = reader.ReadLine()) != null)
                    {
                        if (line.Length == 0 || line[0] == '#') continue;
                        var f = line.Split('\t');
                        if (f.Length < 4) continue;
                        sets[f[0]] = new DemulSet
                        {
                            Name = f[0], Board = f[1], Known = f[2] == "1", Title = f[3],
                            Parent = f.Length > 4 && f[4].Trim().Length > 0 ? f[4].Trim() : null,
                            GdRom = f.Length > 5 && f[5].Trim().Length > 0 ? f[5].Trim() : null,
                        };
                    }
                    Log.Info("set table: " + sets.Count + " sets");
                }
                catch (Exception ex) { Log.Warn("the set table could not be read", ex); }
                return _sets = sets;
            }
        }
    }
}
